#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<pair<long long, long long>> intervals(n);
    for (auto &p : intervals) scanf("%lld %lld", &p.first, &p.second);
    long long ds, de;
    scanf("%lld %lld", &ds, &de);
    sort(intervals.begin(), intervals.end());
    // Merge overlapping or touching [start, end) meetings.
    vector<pair<long long, long long>> merged;
    for (auto [a, b] : intervals) {
        if (!merged.empty() && a <= merged.back().second) merged.back().second = max(merged.back().second, b);
        else merged.push_back({a, b});
    }
    // Subtract the do-not-disturb window, keeping non-empty left/right pieces.
    vector<pair<long long, long long>> result;
    for (auto [a, b] : merged) {
        if (b <= ds || a >= de) result.push_back({a, b});
        else {
            if (a < ds) result.push_back({a, ds});
            if (b > de) result.push_back({de, b});
        }
    }
    string out = to_string(result.size());
    for (auto [a, b] : result) out += ' ' + to_string(a) + ' ' + to_string(b);
    puts(out.c_str());
}

import java.io.*;
