public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        long[][] intervals = new long[n][2];
        for (int i = 0; i < n; i++) {
            st.nextToken(); intervals[i][0] = (long) st.nval;
            st.nextToken(); intervals[i][1] = (long) st.nval;
        }
        st.nextToken(); long ds = (long) st.nval;
        st.nextToken(); long de = (long) st.nval;
        Arrays.sort(intervals, (x, y) -> x[0] != y[0] ? Long.compare(x[0], y[0]) : Long.compare(x[1], y[1]));
        // Merge overlapping or touching [start, end) meetings.
        List<long[]> merged = new ArrayList<>();
        for (long[] p : intervals) {
            if (!merged.isEmpty() && p[0] <= merged.get(merged.size() - 1)[1]) {
                long[] last = merged.get(merged.size() - 1);
                last[1] = Math.max(last[1], p[1]);
            } else merged.add(new long[] {p[0], p[1]});
        }
        // Subtract the do-not-disturb window, keeping non-empty left/right pieces.
        List<long[]> result = new ArrayList<>();
        for (long[] p : merged) {
            long a = p[0], b = p[1];
            if (b <= ds || a >= de) result.add(p);
            else {
                if (a < ds) result.add(new long[] {a, ds});
                if (b > de) result.add(new long[] {de, b});
            }
        }
        StringBuilder sb = new StringBuilder().append(result.size());
        for (long[] p : result) sb.append(' ').append(p[0]).append(' ').append(p[1]);
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := nextInt()
	intervals := make([][2]int, n)
	for i := range intervals {
		intervals[i] = [2]int{nextInt(), nextInt()}
	}
	ds, de := nextInt(), nextInt()
	sort.Slice(intervals, func(i, j int) bool {
		if intervals[i][0] != intervals[j][0] {
			return intervals[i][0] < intervals[j][0]
		}
		return intervals[i][1] < intervals[j][1]
	})
	// Merge overlapping or touching [start, end) meetings.
	var merged [][2]int
	for _, p := range intervals {
		if len(merged) > 0 && p[0] <= merged[len(merged)-1][1] {
			merged[len(merged)-1][1] = max(merged[len(merged)-1][1], p[1])
		} else {
			merged = append(merged, p)
		}
	}
	// Subtract the do-not-disturb window, keeping non-empty left/right pieces.
	var result [][2]int
	for _, p := range merged {
		a, b := p[0], p[1]
		if b <= ds || a >= de {
			result = append(result, p)
		} else {
			if a < ds {
				result = append(result, [2]int{a, ds})
			}
			if b > de {
				result = append(result, [2]int{de, b})
			}
		}
	}
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	out.WriteString(strconv.Itoa(len(result)))
	for _, p := range result {
		out.WriteString(" " + strconv.Itoa(p[0]) + " " + strconv.Itoa(p[1]))
	}
	out.WriteString("\n")
}
